per_case_results.actual_sql:
SELECT "patient_id", "sex", "disease"
FROM "patients"
WHERE "thrombosis_degree" = 'severe';

SELECT "patient_number", "uric_acid", "normal_range"
FROM "patients"
WHERE "patient_number" = 57266;

SELECT COUNT(*) AS "patient_count"
FROM "patients"
WHERE "anti_sm" = 'normal' AND "has_thrombosis" = false;

SELECT MIN("birth_date")
FROM "patients"
WHERE "got_level" > 40 OR "got_level" < 10;
